/*
 * Share Target: receives files shared to the installed app from other apps
 * (e.g. Samsung My Files → Share → babalon JS). Loaded into the service worker generated by
 * vite-plugin-pwa (see `importScripts` in vite.config.ts). The files are kept in a cache and the
 * app opens them after the redirect (see takeSharedFiles in src/files.ts).
 */
self.addEventListener('fetch', (event) => {
  const url = new URL(event.request.url);
  if (event.request.method !== 'POST' || !url.pathname.endsWith('/share-target')) return;
  event.respondWith(
    (async () => {
      const scope = self.registration.scope;
      const data = await event.request.formData();
      const files = data.getAll('files').filter((f) => typeof f !== 'string');
      await caches.delete('babalon-shared');
      const cache = await caches.open('babalon-shared');
      const keys = [];
      for (let i = 0; i < files.length; i++) {
        const file = files[i];
        const key = new URL(`shared/${i}`, scope).href;
        await cache.put(
          key,
          new Response(file, {
            headers: { 'x-name': encodeURIComponent(file.name), 'content-type': file.type || 'application/octet-stream' },
          }),
        );
        keys.push(key);
      }
      await cache.put(new URL('shared/index', scope).href, new Response(JSON.stringify(keys)));
      return Response.redirect(new URL('./?shared=1', scope).href, 303);
    })(),
  );
});
